// ============================================================================
// phone/crypto.ts — THE PHONE'S HALF OF THE CIPHER (docs/plans/phone-link.md, ruling 1).
// ============================================================================
//
// `src/main/phone/crypto.ts` seals; this opens. The two never share a line of code — one is
// `node:crypto` in an Electron main process and the other is pure JavaScript on a phone — so the
// thing that keeps them honest is not an abstraction, it is `crypto.test.ts`, which replays the
// DESKTOP's own vectors (generated by `scripts/gen-vectors.mts` from the desktop module itself)
// through the functions below and fails on any disagreement.
//
// ── WHY PURE JS AND NOT A NATIVE CIPHER (phone-native.md, section 3) ───────────────────────────
//
// `@noble/ciphers` is audited, dependency-free, and runs in Expo Go, in a dev build, in a store
// build and — the deciding property — IN JEST. `expo-crypto` in SDK 57 does offer native AES-GCM
// with AAD, and it would have been a legitimate choice, but a native module cannot execute under
// `node`, so the conformance vectors would have become a claim instead of a test.
//
// ── FOUR RULES, THE SAME FOUR THE DESKTOP KEEPS ────────────────────────────────────────────────
//
//  1. AES-256-GCM, a 12-byte nonce, a 16-byte tag. The key is the 32 raw `viewKey` bytes.
//  2. THE AAD IS `phone-v1|<channel>|<seq>`. A frame cannot be replayed onto another channel or
//     re-ordered onto another sequence number, even by somebody holding the key.
//  3. THE TAG IS AT THE FRONT ON THE WIRE (`d = base64url(tag ‖ ciphertext)`), so a truncated
//     frame fails a length check instead of authenticating a prefix. Every GCM library wants it at
//     the BACK; `split` below is the one place the two conventions meet.
//  4. NOTHING HERE THROWS. A refusal is `null`. And because a frame that legitimately says "no
//     fight" decrypts to the value `null`, a success is a BOX — `{ value }` — so that the caller
//     can tell "the desk said nothing is happening" from "this phone cannot read this".

import { gcm } from '@noble/ciphers/aes.js'
import { bytesToUtf8, utf8ToBytes } from '@noble/ciphers/utils.js'
import { PHONE_PROTOCOL, type PhoneChannel } from '@shared/phone/types'

export const NONCE_BYTES = 12
export const TAG_BYTES = 16
export const KEY_BYTES = 32

/** What a sealed value opens to. `null` is a refusal; `{ value: null }` is the payload `null`. */
export interface Opened {
  value: unknown
}

/** The two wire fields of one frame, straight off the relay. */
export interface SealedFrame {
  n: string
  d: string
}

// -------------------------------------------------------------------------------- base64url

const ALPHABET = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_'

const REVERSE = ((): Int8Array => {
  const table = new Int8Array(128).fill(-1)
  for (let i = 0; i < ALPHABET.length; i++) table[ALPHABET.charCodeAt(i)] = i
  return table
})()

/**
 * base64url → bytes, or `null` for anything that is not base64url.
 *
 * WRITTEN OUT RATHER THAN `atob`: `atob` is standard base64, it throws on `-` and `_`, it throws
 * on a bad length, and its presence on a React Native runtime is a version question. Thirty lines
 * of table lookup is not worth a platform assumption in the one module that must never throw.
 */
export function fromBase64Url(text: string): Uint8Array | null {
  const n = text.length
  if (n % 4 === 1) return null
  const out = new Uint8Array(Math.floor((n * 3) / 4))
  let acc = 0
  let bits = 0
  let at = 0
  for (let i = 0; i < n; i++) {
    const code = text.charCodeAt(i)
    const six = code < 128 ? REVERSE[code] : -1
    if (six === undefined || six < 0) return null
    acc = (acc << 6) | six
    bits += 6
    if (bits >= 8) {
      bits -= 8
      out[at++] = (acc >> bits) & 0xff
    }
  }
  return out.subarray(0, at)
}

/** bytes → base64url, unpadded. Used for the at-rest blob and for nothing on the wire. */
export function toBase64Url(bytes: Uint8Array): string {
  let out = ''
  let acc = 0
  let bits = 0
  for (const byte of bytes) {
    acc = (acc << 8) | byte
    bits += 8
    while (bits >= 6) {
      bits -= 6
      out += ALPHABET.charAt((acc >> bits) & 0x3f)
    }
  }
  if (bits > 0) out += ALPHABET.charAt((acc << (6 - bits)) & 0x3f)
  return out
}

// ------------------------------------------------------------------------------------ frames

/** Rule 2: the generation, the channel and the place in the sequence, as bytes. */
export function frameAad(channel: PhoneChannel, seq: number): Uint8Array {
  return utf8ToBytes(`${PHONE_PROTOCOL}|${channel}|${String(seq)}`)
}

/** Rule 3: `tag ‖ ciphertext` off the wire becomes the `ciphertext ‖ tag` every GCM wants. */
function split(blob: Uint8Array): Uint8Array | null {
  if (blob.length < TAG_BYTES) return null
  const out = new Uint8Array(blob.length)
  out.set(blob.subarray(TAG_BYTES), 0)
  out.set(blob.subarray(0, TAG_BYTES), blob.length - TAG_BYTES)
  return out
}

/** Decrypt, parse, box. Every failure on the way answers `null` (rule 4). */
function open(key: Uint8Array, nonce: Uint8Array, body: Uint8Array, aad: Uint8Array): Opened | null {
  try {
    const plain = gcm(key, nonce, aad).decrypt(body)
    return { value: JSON.parse(bytesToUtf8(plain)) as unknown }
  } catch {
    return null
  }
}

/** Seal, the other direction. Only the at-rest cache uses it; nothing on this app sends a frame. */
function seal(key: Uint8Array, nonce: Uint8Array, value: unknown, aad: Uint8Array): Uint8Array {
  const body = gcm(key, nonce, aad).encrypt(utf8ToBytes(JSON.stringify(value ?? null)))
  const out = new Uint8Array(body.length)
  out.set(body.subarray(body.length - TAG_BYTES), 0)
  out.set(body.subarray(0, body.length - TAG_BYTES), TAG_BYTES)
  return out
}

/**
 * ONE RELAYED FRAME. `viewKey` is base64url of the 32 raw key bytes — the `k` of the pair link.
 *
 * A wrong key, a wrong channel, a wrong sequence, a flipped byte, a truncated blob, a nonce of the
 * wrong length and a payload that is not JSON all answer `null`, and `crypto.test.ts` asserts each
 * one separately against the desktop's own vectors.
 */
export function openFrame(
  viewKey: string,
  channel: PhoneChannel,
  seq: number,
  frame: SealedFrame
): Opened | null {
  const key = fromBase64Url(viewKey)
  const nonce = fromBase64Url(frame.n)
  const blob = fromBase64Url(frame.d)
  if (!key || !nonce || !blob) return null
  if (key.length !== KEY_BYTES || nonce.length !== NONCE_BYTES) return null
  const body = split(blob)
  if (!body) return null
  return open(key, nonce, body, frameAad(channel, seq))
}

// ----------------------------------------------------------------------------- the cache blob

/** The at-rest generation. Separate from the wire's, so one can move without the other. */
export const CACHE_PROTOCOL = 'phone-cache-v1'

/** The at-rest AAD: the generation and the cache entry's NAME, so two entries cannot be swapped. */
export function cacheAad(name: string): Uint8Array {
  return utf8ToBytes(`${CACHE_PROTOCOL}|${name}`)
}

/**
 * The carried character, on disk (ruling 8). `nonce ‖ tag ‖ ciphertext` as one base64url string:
 * the same tag-at-a-fixed-offset rule as the wire, for the same reason, and one string because the
 * file system is not a place to keep three fields in step.
 */
export function sealCache(key: Uint8Array, name: string, value: unknown, nonce: Uint8Array): string {
  const body = seal(key, nonce, value, cacheAad(name))
  const out = new Uint8Array(nonce.length + body.length)
  out.set(nonce, 0)
  out.set(body, nonce.length)
  return toBase64Url(out)
}

/** …and back. A wrong key, a truncated file and a tampered byte all answer `null`. */
export function openCache(key: Uint8Array, name: string, text: string): Opened | null {
  const raw = fromBase64Url(text)
  if (!raw || raw.length < NONCE_BYTES + TAG_BYTES) return null
  const body = split(raw.subarray(NONCE_BYTES))
  if (!body) return null
  return open(key, raw.subarray(0, NONCE_BYTES), body, cacheAad(name))
}
